  const KODLAR = DILLER.map((d) => d.kod);
  const TABLO = {};
  for (const k of KODLAR) TABLO[k] = {};
  for (const satir of SATIRLAR) {
    const anahtar = satir[0];
    KODLAR.forEach((k, i) => {
      TABLO[k][anahtar] = satir[i + 1];
    });
  }

  // Çeviri: seçili dilde yoksa İngilizce, o da yoksa Türkçe, o da yoksa anahtarın kendisi.
  function t(dil, anahtar, vars) {
    let s = (TABLO[dil] && TABLO[dil][anahtar]) ?? TABLO.en[anahtar] ?? TABLO.tr[anahtar] ?? anahtar;
    if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m));
    return s;
  }

  const disa = { DILLER, SATIRLAR, TABLO, t, varsayilan: "tr" };
  if (typeof module !== "undefined" && module.exports) module.exports = disa;
  else kok.DILLER_API = disa;
